  "name": "Weather warning",
  "description": "Shows severe weather warnings as an area.",
  "type": "extension",
  "script": "main.js"
}

script.code:
// main.js – an ES module in a single file
export function activate(wmap) {
  wmap.onMapReady((map) => {
    map.addSource('warning', { type: 'geojson', data: 'https://example.org/warnings.geojson' });
    map.addLayer({ id: 'warning', type: 'fill', source: 'warning',
      paint: { 'fill-color': '#e03131', 'fill-opacity': 0.3 } });
  });
  wmap.addMenuItem('warning', 'Warnings', () => wmap.toast('Warnings on'));
}
